package com.mavric.health.identity;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.mail.*;
import org.springframework.mail.javamail.JavaMailSender;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.mock.web.MockHttpServletRequest;
import com.mavric.health.audit.TraceContext;
import com.mavric.health.shared.*;
import com.mavric.health.persistence.sqlserver.*;
import com.mavric.health.persistence.sqlserver.SqlServerIdentityStoreTest.ModelTransactionManager;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.mockito.ArgumentMatchers.*;
/** Sender is ALWAYS Mockito mock. Manual cycles only; no scheduler, SMTP, network or database. */
class MailDeliverySqlServerTest {
 static final String ONE="aa000000-0000-4000-8000-000000000001",TWO="aa000000-0000-4000-8000-000000000002";
 final SqlServerExecutor executor=mock(SqlServerExecutor.class);final ModelTransactionManager manager=new ModelTransactionManager();final JavaMailSender sender=mock(JavaMailSender.class);final Sql sql=mock(Sql.class);final MailDelivery delivery=new MailDelivery(new SqlServerMailDeliveryStore(executor,manager),sender,"sender@example.test");
 List<Map<String,Object>> claimed=List.of(mail(ONE),mail(TWO));boolean claimFailure,completeFailure,sendFailure,ambiguousFailure;final List<List<Object>> completes=new ArrayList<>();int claims;
 MailDeliverySqlServerTest(){when(executor.execute(any(),any(),any(Object[].class))).thenAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var sp=inv.<SqlServerProcedure>getArgument(0);assertEquals(new SqlServerContext(null,null,null,null,null,null,null,null,null,SqlServerContext.Scope.WORKER),inv.getArgument(1));var args=Arrays.asList(((Object[])inv.getRawArguments()[2]).clone());if(sp==SqlServerProcedure.MAIL_CLAIM){claims++;manager.events.add("claim");if(claimFailure)throw new RuntimeException("canary driver");return new SqlServerExecutor.Result(List.of(claimed),List.of());}assertEquals(SqlServerProcedure.MAIL_COMPLETE,sp);completes.add(args);manager.events.add("complete:"+args.get(2));if((completeFailure&&args.get(2).equals("SENT")||ambiguousFailure&&args.get(2).equals("AMBIGUOUS"))&&args.getFirst().equals(ONE))throw new RuntimeException("canary complete");return new SqlServerExecutor.Result(List.of(),List.of());});doAnswer(inv->{assertFalse(TransactionSynchronizationManager.isActualTransactionActive());int claimIndex=manager.events.lastIndexOf("claim");assertTrue(claimIndex>=0);assertEquals("commit",manager.events.get(claimIndex+1));var message=inv.<SimpleMailMessage>getArgument(0);manager.events.add("send");assertEquals("sender@example.test",message.getFrom());assertEquals("qa@example.test",message.getTo()[0]);assertEquals("Synthetic",message.getSubject());assertEquals("Synthetic body",message.getText());if(sendFailure&&Collections.frequency(manager.events,"send")==1)throw new MailSendException("canary SMTP");return null;}).when(sender).send(any(SimpleMailMessage.class));}
 static Map<String,Object> mail(String id){return Map.of("id",id,"recipient","qa@example.test","subject","Synthetic","body","Synthetic body","claimVersion",1);}
 @AfterEach void cleanup(){TraceContext.REQUEST.remove();SecurityContextHolder.clearContext();TransactionSynchronizationManager.clear();}
 @Test void claimCommitsBeforeMockSenderAndEachCompleteCommitsBeforeNextRow() throws Exception {delivery.send();assertEquals(List.of("begin:0","claim","commit","send","begin:0","complete:SENT","commit","send","begin:0","complete:SENT","commit"),manager.events);assertEquals(List.of(List.of(ONE,1,"SENT"),List.of(TWO,1,"SENT")),completes);verify(sender,times(2)).send(any(SimpleMailMessage.class));assertEquals(1,claims);var scheduled=MailDelivery.class.getMethod("send").getAnnotation(org.springframework.scheduling.annotation.Scheduled.class);assertEquals(5000,scheduled.fixedDelay());assertEquals(10000,scheduled.initialDelay());}
 @Test void emptyClaimAndClaimOrCommitFailuresNeverSend(){claimed=List.of();delivery.send();verifyNoInteractions(sender);claimFailure=true;delivery.send();verifyNoInteractions(sender);claimFailure=false;claimed=List.of(mail(ONE));manager.failCommit=true;delivery.send();verifyNoInteractions(sender);assertTrue(completes.isEmpty());}
 @Test void senderExceptionIsAmbiguousButRemainingRowsContinue(){sendFailure=true;delivery.send();assertEquals(List.of(List.of(ONE,1,"AMBIGUOUS"),List.of(TWO,1,"SENT")),completes);verify(sender,times(2)).send(any(SimpleMailMessage.class));assertEquals(1,claims);}
 @Test void completeSentFailureNeverReclassifiesOrResends(){completeFailure=true;delivery.send();assertEquals(List.of(List.of(ONE,1,"SENT"),List.of(TWO,1,"SENT")),completes);verify(sender,times(2)).send(any(SimpleMailMessage.class));assertEquals(1,claims);}
 @Test void ambiguousCompleteFailureNeverRetriesAndFatalErrorPropagates(){sendFailure=true;ambiguousFailure=true;delivery.send();assertEquals(List.of(List.of(ONE,1,"AMBIGUOUS"),List.of(TWO,1,"SENT")),completes);reset(sender);var fatal=new AssertionError("synthetic fatal");doThrow(fatal).when(sender).send(any(SimpleMailMessage.class));int old=completes.size();assertSame(fatal,assertThrows(AssertionError.class,delivery::send));assertEquals(old,completes.size());}
 @Test void outerTransactionSkipsClaimAndContextIsNeverReadOrChanged(){var request=new MockHttpServletRequest("POST","/forged");TraceContext.REQUEST.set(request);var authentication=new org.springframework.security.authentication.UsernamePasswordAuthenticationToken("forged",null);SecurityContextHolder.getContext().setAuthentication(authentication);manager.outer(()->{delivery.send();return null;});verifyNoInteractions(executor,sender);assertSame(request,TraceContext.REQUEST.get());assertSame(authentication,SecurityContextHolder.getContext().getAuthentication());delivery.send();assertSame(request,TraceContext.REQUEST.get());assertSame(authentication,SecurityContextHolder.getContext().getAuthentication());}
 @Test void failuresLogOnlyStaticWarnWithoutCanaryOrThrowable(){var logger=(ch.qos.logback.classic.Logger)org.slf4j.LoggerFactory.getLogger(MailDelivery.class);var appender=new ch.qos.logback.core.read.ListAppender<ch.qos.logback.classic.spi.ILoggingEvent>();appender.start();logger.addAppender(appender);try{sendFailure=true;ambiguousFailure=true;delivery.send();assertEquals(2,appender.list.size());for(var event:appender.list){assertEquals("Mail delivery cycle unavailable",event.getFormattedMessage());assertEquals(ch.qos.logback.classic.Level.WARN,event.getLevel());assertNull(event.getThrowableProxy());}}finally{logger.detachAppender(appender);appender.stop();}}
 @Test void minimalSpringSelectsLegacyWithoutStartingSchedulerOrDatasource(){try(var context=new AnnotationConfigApplicationContext()){context.getEnvironment().getPropertySources().addFirst(new org.springframework.core.env.MapPropertySource("synthetic",Map.of("health.mail.from","sender@example.test")));context.registerBean(Sql.class,()->sql);context.registerBean(JavaMailSender.class,()->sender);context.registerBean(MailDelivery.class);context.refresh();verifyNoInteractions(sql,sender);when(sql.rows(anyString(),any(Object[].class))).thenReturn(List.of());context.getBean(MailDelivery.class).send();verify(sql).rows(anyString(),any(Object[].class));verifyNoInteractions(executor);assertEquals(0,context.getBeanNamesForType(SqlServerMailDeliveryStore.class).length);assertEquals(0,context.getBeanNamesForType(javax.sql.DataSource.class).length);}}
 @Test void malformedLaterClaimRowPreventsAllSendsAndRollsBackClaim(){var invalid=new LinkedHashMap<>(mail(TWO));invalid.remove("body");claimed=List.of(mail(ONE),invalid);delivery.send();verifyNoInteractions(sender);assertTrue(completes.isEmpty());assertEquals(1,claims);assertEquals("rollback",manager.events.getLast());}

}
